async function api(path,init={}){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);
  try{const r=await fetch(path,{credentials:'same-origin',signal:controller.signal,...init});
    const x=await r.json().catch(()=>({error:'El servidor no devolvió una respuesta válida.'}));
    if(!r.ok){const error=Error(x.error||'No se pudo completar la solicitud.');error.status=r.status;error.code=x.code;throw error}return x;
  }catch(error){if(error.name==='AbortError')throw Error('La fuente tardó demasiado en responder. Reintente la lectura.');throw error}finally{clearTimeout(timer)}
}
