    if(!data||!data.coverage||!data.charts||!data.business||!data.insights)throw Error('La respuesta no contiene un dataset válido. Revise la salud de las fuentes.');
    const hasData=Object.values(data.coverage.sources||{}).some(source=>Number(source.rows)>0);
