async function downloadExport(type,extra={}){
  const generation=refreshID,query=new URLSearchParams(Object.fromEntries(Object.entries({...V.filter,...extra,type}).filter(([,v])=>v!==''&&v!==null&&v!==undefined)));
  try{
    const response=await fetch('/api/exports?'+query,{credentials:'same-origin'});
    if(generation!==refreshID)return;
    if(!response.ok){const body=await response.json().catch(()=>({}));throw Error(body.error||'No se pudo preparar la exportación.')}
    if(!response.headers.get('content-type')?.includes('text/csv'))throw Error('La descarga requiere acceso a la fuente. Revise su sesión.');
    const blob=await response.blob();if(generation!==refreshID)return;
    const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='greencall-'+type+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Descarga preparada.');
  }catch(error){if(generation===refreshID)toast(error.message)}
}
