function fillFilters(){const d=V.data,b=d.business||{},s=[...new Set([...(b.catalog||[]).map(x=>x.sku),...(d.charts?.abc||[]).map(x=>x.sku)])],t=[...(b.techs||[]).map(x=>x.code),...(b.locations||[]).map(x=>x.tech)],c=d.charts?.centers||[],w=d.charts?.warehouses||[],techs=d.charts?.technologies||[];const tnames=new Map([...(b.techs||[]).map(x=>[x.code,x.name]),...(b.locations||[]).map(x=>[x.tech,x.name])]);for(const [key,values] of [['Sku',s],['Tech',t],['Center',c],['Warehouse',w],['Technology',techs]]){const el=$('f'+key),first=el.options[0].text;el.innerHTML=`<option value="">${first}</option>`+[...new Set(values)].filter(Boolean).sort((a,b)=>String(a).localeCompare(String(b))).map(x=>{const label=key==='Tech'?(tnames.get(x)||x)+' · '+x:key==='Sku'?(b.catalog||[]).find(y=>y.sku===x)?.description||x:x;return `<option value="${esc(x)}" title="${esc(x)}">${esc(label)}</option>`}).join('');el.value=V.filter[key.toLowerCase()]||''}for(const k of ['From','To'])$('f'+k).value=V.filter[k.toLowerCase()]||'';$('cutBadge').textContent='Inventario: '+(d.coverage.cuts?.inventory_eta||'sin corte');$('warning').hidden=!!d.coverage.fullGoogleHistory;$('warning').querySelector('strong').textContent='Cobertura parcial de las fuentes';$('warning').querySelector('div > span').textContent=d.coverage.notice||'Consulte los cortes y la cobertura antes de interpretar los indicadores.'}
