function card(name,value,note,ico='◈',color='#d97706',isMoney=false){let shown=typeof value==='string'?value:isMoney&&Math.abs(Number(value))>=1000000?'₡'+(Number(value)/1000000).toLocaleString('es-CR',{maximumFractionDigits:2})+' M':isMoney?crc(value):nfmt(value);let v=value===null||value===undefined?'<span class="value-pending">Sin fuente suficiente</span>':esc(shown);return `<article class="kpi" style="--accent:${color}" title="${esc(name+' · '+note+(isMoney&&value!==null?' · '+crc(value):''))}"><div class="kpi-head"><span class="kpi-name">${esc(name)}</span><span class="kpi-icon">${ico}</span></div><div class="kpi-value">${v}</div><div class="kpi-note">${esc(note)}</div></article>`}
