function tableBody(t){const q=t.q.trim().toLocaleLowerCase('es');let rows=q?t.data.filter(r=>t.columns.some(c=>String(r[c[0]]??'').toLocaleLowerCase('es').includes(q))):t.data;if(t.sort){const k=t.sort,d=t.dir;rows=[...rows].sort((a,b)=>{const x=a[k],y=b[k];if(x==null)return y==null?0:1;if(y==null)return -1;return (typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'es',{numeric:true}))*d})}const pages=Math.max(1,Math.ceil(rows.length/t.size));t.page=Math.min(t.page,pages-1);const from=t.page*t.size,slice=rows.slice(from,from+t.size);return {rows,pages,from,slice}}
function renderTable(id){const t=TABLES.get(id),box=document.getElementById(id);if(!t||!box)return;const {rows,pages,from,slice}=tableBody(t);box.querySelector('tbody').innerHTML=slice.length?slice.map(r=>`<tr>${t.columns.map(c=>cellHTML(r,c)).join('')}</tr>`).join(''):`<tr><td colspan="${t.columns.length}" class="muted-cell">Sin coincidencias para “${esc(t.q)}”.</td></tr>`;box.querySelectorAll('th[data-sort]').forEach(th=>th.setAttribute('aria-sort',th.dataset.sort===t.sort?(t.dir>0?'ascending':'descending'):'none'));const info=box.querySelector('[data-tbl-info]');if(info)info.textContent=rows.length?`${nfmt(from+1)}–${nfmt(from+slice.length)} de ${nfmt(rows.length)}${t.q?' (filtrado de '+nfmt(t.data.length)+')':''} · página ${t.page+1} de ${pages}`:`0 de ${nfmt(t.data.length)}`;const prev=box.querySelector('[data-tbl-page="-1"]'),next=box.querySelector('[data-tbl-page="1"]');if(prev)prev.disabled=t.page===0;if(next)next.disabled=t.page>=pages-1}
function table(data,columns,limit=12){if(!data?.length)return empty();const id='tbl'+(++tableSeq),size=data.length<=limit?Math.max(limit,1):[20,50,100].reduce((a,b)=>Math.abs(b-limit)<Math.abs(a-limit)?b:a,20);TABLES.set(id,{data,columns,page:0,size,q:'',sort:'',dir:1});const t=TABLES.get(id),{slice}=tableBody(t),paged=data.length>size;return `<div class="tbl" id="${id}">${paged?`<div class="tbl-tools"><input type="search" data-tbl-q placeholder="Buscar en ${nfmt(data.length)} filas" aria-label="Buscar en la tabla"><label>Filas <select data-tbl-size aria-label="Filas por página">${[20,50,100].map(n=>`<option ${n===size?'selected':''}>${n}</option>`).join('')}</select></label></div>`:''}<div class="table-wrap"><table class="data-table"><thead><tr>${columns.map(c=>`<th scope="col" data-sort="${esc(c[0])}" aria-sort="none" class="sortable" tabindex="0" title="Ordenar">${esc(c[1])}</th>`).join('')}</tr></thead><tbody>${slice.map(r=>`<tr>${columns.map(c=>cellHTML(r,c)).join('')}</tr>`).join('')}</tbody></table></div>${paged?`<div class="pagination"><span data-tbl-info aria-live="polite">1–${nfmt(slice.length)} de ${nfmt(data.length)} · página 1 de ${Math.ceil(data.length/size)}</span><span><button type="button" data-tbl-page="-1" disabled>‹ Anterior</button> <button type="button" data-tbl-page="1">Siguiente ›</button></span></div>`:''}</div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tbl-page]'),th=e.target.closest('.tbl th[data-sort]');const box=e.target.closest('.tbl');if(!box)return;const t=TABLES.get(box.id);if(!t)return;if(b){t.page=Math.max(0,t.page+Number(b.dataset.tblPage));renderTable(box.id)}else if(th){t.dir=t.sort===th.dataset.sort?-t.dir:1;t.sort=th.dataset.sort;t.page=0;renderTable(box.id)}});
document.addEventListener('keydown',e=>{const th=e.target.closest?.('.tbl th[data-sort]');if(th&&(e.key==='Enter'||e.key===' ')){e.preventDefault();th.click()}});
document.addEventListener('input',e=>{const box=e.target.closest?.('.tbl');if(!box||!e.target.matches('[data-tbl-q]'))return;const t=TABLES.get(box.id);t.q=e.target.value;t.page=0;renderTable(box.id)});
document.addEventListener('change',e=>{const box=e.target.closest?.('.tbl');if(!box||!e.target.matches('[data-tbl-size]'))return;const t=TABLES.get(box.id);t.size=Number(e.target.value);t.page=0;renderTable(box.id)});
