function horizonValidation(current,orders,horizon){
  const rows=[['Material seleccionado',current],['Órdenes únicas',orders]].map(([label,series])=>{
    const evaluation=series.evaluation?.by_horizon?.[horizon],scored=evaluation?.status==='EVALUADO';
    return {series:label,status:scored?'Evaluado':'Historia insuficiente',leads:evaluation?'M+'+evaluation.lead_start+' a M+'+evaluation.lead_end:'—',origins:scored?evaluation.backtests:null,pairs:scored?evaluation.observations:null,mae:scored?evaluation.mae:null,wape:scored?evaluation.wape:null,smape:scored?evaluation.smape:null,baseline_mae:scored?evaluation.baseline?.mae:null,baseline_wape:scored?evaluation.baseline?.wape:null};
  });
  return heading('Validación a '+horizon+' meses','Se vuelve a elegir el modelo con el pasado disponible en cada corte, antes de pronosticar los meses siguientes.')+`<div class="panel" id="horizonValidation" data-horizon="${horizon}">${table(rows,[['series','Serie'],['status','Estado'],['leads','Tramo desde cada corte'],['origins','Cortes','num'],['pairs','Pares corte–mes','num'],['mae','MAE','num'],['wape','WAPE %','num'],['smape','sMAPE %','num'],['baseline_mae','MAE última observación','num'],['baseline_wape','WAPE última observación %','num']],2)}<p>Comparación con la última observación sobre los mismos meses. Se requieren al menos tres cortes completos. Los cortes pueden solaparse; cada par corte–mes tiene el mismo peso. Esta validación evalúa la selección automática, no garantiza el error futuro del modelo final. Un WAPE sin demanda en el denominador queda sin calcular.</p></div>`;
}
