let tableRequest=0;async function loadTable(){const request=++tableRequest,generation=refreshID,dataset=V.data;try{const z=await api('/api/rows?'+new URLSearchParams({type:V.table.type,offset:String(V.table.offset),limit:String(V.table.limit),q:V.table.q,sort:V.table.sort,dir:V.table.dir}));if(V.table.offset>=z.total&&z.total>0){V.table.offset=0;return loadTable()}if(!$('rowResults')||generation!==refreshID||dataset!==V.data||request!==tableRequest)return;const headers=Object.keys(z.rows[0]||{}).filter(k=>!k.startsWith('_'));$('rowResults').innerHTML=table(z.rows,headers.map(k=>[k,k+(V.table.sort===k?(V.table.dir==='desc'?' ▼':' ▲'):' ↕')]),V.table.limit);$('rowResults').querySelectorAll('th').forEach((th,i)=>{th.title='Ordenar por '+headers[i];th.tabIndex=0;th.classList.add('sortable');const toggle=()=>{const col=headers[i];V.table.dir=V.table.sort===col&&V.table.dir==='asc'?'desc':'asc';V.table.sort=col;V.table.offset=0;loadTable()};th.onclick=toggle;th.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}}});$('rowPage').textContent=`${nfmt(z.offset+Math.min(z.limit,z.total))} de ${nfmt(z.total)}`;$('rowPrev').disabled=z.offset===0;$('rowNext').disabled=z.offset+z.limit>=z.total}catch(e){toast(e.message)}}
function admin(c,d){const status=V.authenticated;c.innerHTML=heading('Administración y fuentes','Google Sheets de solo lectura · importación local de respaldo · sin cambiar producción')+`<div class="panel"><h3>Acceso administrativo</h3><p>La clave se muestra en la consola de RUN_LOCAL.cmd. No hay usuario ni clave predefinida dentro del ZIP; la aplicación escucha solo en 127.0.0.1.</p>${status?`<div class="login-grid"><span class="chip good">✓ Sesión local autorizada</span><button class="btn-quiet" id="logout">Cerrar sesión</button></div>`:`<div class="login-grid"><input type="password" id="adminKey" placeholder="Clave temporal de esta ejecución" autocomplete="current-password" name="admin-token" aria-label="Clave administrativa"><button class="btn-primary" id="login">Desbloquear importadores</button></div>`}</div>`+`<div class="panel" style="margin-top:15px"><div class="table-tools"><div><h3>Google Sheets · Fuente principal</h3><p>Actualización automática con cuenta de servicio y permiso de visualización. El servidor lee, procesa y guarda un snapshot local; nunca escribe en Google Sheets.</p></div><span id="sheetLiveBadge" class="chip">SIN CONFIGURAR</span></div><div class="grid2"><div><label for="sheetID" class="gc-sync-label">ID del Google Sheets</label><input style="width:100%" id="sheetID" placeholder="ID del documento" ${status?'':'disabled'}><label for="sheetKeyPath" class="gc-sync-label">Ruta JSON de cuenta de servicio (solo en este equipo)</label><input style="width:100%" id="sheetKeyPath" placeholder="C:\\credenciales\\greencall-readonly.json" autocomplete="off" ${status?'':'disabled'}><small>La clave privada no se copia al ZIP ni se envía al navegador. Comparta el Sheets como lector con el correo de la cuenta de servicio.</small></div><div><label for="sheetInterval" class="gc-sync-label">Sincronizar cada (minutos)</label><input id="sheetInterval" type="number" min="5" max="120" value="10" ${status?'':'disabled'}><label for="sheetFull" class="gc-sync-label">Reconciliación completa cada (horas)</label><input id="sheetFull" type="number" min="1" max="168" value="24" ${status?'':'disabled'}><small>Primera vez: descarga completa. Luego: últimos 3.000 registros de Consumos y snapshot completo de las demás pestañas; conciliación total cada 24 h. Solo mientras RUN_LOCAL.cmd siga abierto.</small></div></div><div class="sync-buttons"><button class="btn-primary" id="sheetSave" ${status?'':'disabled'}>Guardar configuración</button><button id="sheetTest" class="btn-quiet" ${status?'':'disabled'}>Probar acceso</button><button id="sheetIncremental" class="btn-primary" ${status?'':'disabled'}>Sincronizar ahora</button><button id="sheetFullSync" class="btn-quiet" ${status?'':'disabled'}>Reconciliar todo</button><button id="sheetStop" class="btn-quiet" ${status?'':'disabled'}>Desactivar</button></div><div class="import-log" id="sheetProgress">Consultando estado de Google Sheets…</div><small>Si falla una pestaña, no se reemplaza parcialmente la información previa. Los históricos precargados siguen disponibles si no hay Internet.</small></div>`+`<details class="legacy-panel"><summary>Contingencia y parámetros avanzados <small>Solo administración</small></summary><div class="grid2 legacy-content"><div class="panel"><h3>Recuperación administrativa · importadores legacy</h3><p>Recurso de contingencia para recuperar fuentes. En operación habitual cargue únicamente el Excel de toma física desde su módulo.</p><div class="dropzone" id="dropzone"><strong>⇧ Arrastre archivos aquí</strong><small>Admite múltiples archivos, columnas reordenadas y encabezados sin tildes.</small><input type="file" id="files" aria-label="Archivos de recuperación administrativa" accept=".xlsx,.xlsm,.csv" multiple ${status?'':'disabled'}></div><div class="sap-cut"><label for="sapCutDate">Corte para <b>Cantidades SAP</b> sin fecha propia (opcional)</label><input id="sapCutDate" type="date"><small>Solo para importar Cantidades SAP. No se inventa fecha si queda vacío.</small></div><div class="login-grid" style="margin-top:10px"><button class="btn-primary" id="analyze" ${status?'':'disabled'}>Analizar / previsualizar</button><button class="btn-primary" id="apply" ${status?'':'disabled'}>Aplicar previews seleccionadas</button></div><div id="preview" class="import-log">${V.staged.length?V.staged.map(x=>`<div class="stat-row"><label><input type="checkbox" class="import-select" value="${x.id}" checked> ${esc(x.filename)}</label><span>${x.records.map(z=>esc(z.type||'No reconocido')+' ('+nfmt(z.received)+')').join(', ')}</span></div>`).join(''):'<p class="muted">No hay archivos preparados para aplicar.</p>'}</div></div><div class="panel"><h3>Fuentes actuales</h3>${sourceStats(d)}<h3 style="margin-top:20px">Planificación · umbrales configurables</h3><p>Estos valores son parámetros operativos ilustrativos, no políticas oficiales de GreenCall.</p><div class="stat-row"><span>Crítico por cobertura (días)</span><input id="critical" aria-label="Cobertura crítica en días" type="number" min="1" max="365" value="7"></div><div class="stat-row"><span>Alto (días)</span><input id="high" aria-label="Cobertura alta en días" type="number" min="1" max="365" value="15"></div><div class="stat-row"><span>Medio (días)</span><input id="medium" aria-label="Cobertura media en días" type="number" min="1" max="365" value="30"></div><div class="stat-row"><span>Lead time global (opcional)</span><input id="lead" type="number" min="1" max="365" placeholder="Sin parametrizar…" aria-label="Lead time global en días"></div><div style="margin:12px 0"><label style="font-size:11px;font-weight:750">Aliases validados (pseudo-SKU=SKU oficial, una línea por material)</label><textarea id="aliases" aria-label="Aliases validados" rows="3" style="width:100%;resize:vertical;padding:8px;border:1px solid #eadfce;border-radius:8px" placeholder="PEND-EJEMPLO=1234567"></textarea></div><button class="btn-primary" id="saveSettings" ${status?'':'disabled'}>Guardar configuración</button><p>La compra sugerida permanece inactiva hasta confirmar lead time y stock vigente por SKU.</p></div></div></details>`;if(status){$('logout').onclick=logout;$('files').onchange=()=>toast($('files').files.length+' archivo(s) seleccionados');const dz=$('dropzone');dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag')};dz.ondragleave=()=>dz.classList.remove('drag');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('drag');V.dropFiles=[...e.dataTransfer.files];toast(`${V.dropFiles.length} archivos listos para analizar`)};$('analyze').onclick=analyzeFiles;$('apply').onclick=applyFiles;$('saveSettings').onclick=async()=>{try{const b={critical_days:+$('critical').value,high_days:+$('high').value,medium_days:+$('medium').value,lead_time:$('lead').value||null,aliases:Object.fromEntries(($('aliases')?.value||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).filter(line=>line.includes('=')).map(line=>line.split('=').map(x=>x.trim().toUpperCase())).filter(a=>a.length===2&&a[0]&&a[1]))};await api('/api/config',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});toast('Parámetros locales actualizados');await refresh()}catch(e){toast(e.message)}};api('/api/config').then(s=>{if($('critical')){$('critical').value=s.critical_days;$('high').value=s.high_days;$('medium').value=s.medium_days;$('lead').value=s.lead_time??'';if($('aliases'))$('aliases').value=Object.entries(s.aliases||{}).map(([k,v])=>k+'='+v).join('\n')}})}else $('login').onclick=async()=>{try{await api('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token:$('adminKey').value})});V.authenticated=true;toast('Acceso habilitado');render()}catch(e){toast(e.message)}};connectSheetUI(status)}
async function connectSheetUI(adminAllowed){
  const put=async()=>{try{const q=await api('/api/sheets/status');if(!$('sheetProgress'))return;
    if(document.activeElement!==$('sheetID'))$('sheetID').value=q.spreadsheet_id||'';
    if(document.activeElement!==$('sheetInterval'))$('sheetInterval').value=q.interval_minutes||10;
    if(document.activeElement!==$('sheetFull'))$('sheetFull').value=q.full_every_hours||24;
    const stage=q.progress||{},on=q.enabled&&q.credential_configured;
    $('sheetLiveBadge').textContent=({SINCRONIZANDO:'SINCRONIZANDO',CONECTADO:'LECTURA CONFIRMADA',ERROR:'ERROR · RESPALDO LOCAL',PRECARGADOS:'DATOS PRECARGADOS'})[q.state]||'SIN VERIFICAR';
    $('sheetLiveBadge').className='chip '+(q.state==='CONECTADO'?'good':q.state==='ERROR'?'warn':'');
    $('sheetProgress').innerHTML=`<b>Último intento:</b> ${esc(q.last_attempt||'Sin ejecutar')} · <b>Última lectura exitosa:</b> ${esc(q.last_sync_at||'Sin ejecutar')} · <b>Estado:</b> ${esc(stage.phase||'pendiente')} ${stage.tab?'· '+esc(stage.tab):''} (${nfmt(stage.processed||0)}/${nfmt(stage.total||0)}) ${q.busy?'<span class="chip">Leyendo origen...</span>':''}<br><b>Última reconciliación completa:</b> ${esc(q.last_full_at||'Pendiente')} ${q.last_error?'<p class="warning-inline">'+esc(q.last_error)+'</p>':''}<br><b>Fuentes:</b> ${Object.entries(q.source_log||{}).map(([n,r])=>esc(n)+' '+nfmt(r.rows)).join(' · ')||'Sin sincronizar todavía'}`;
    for(const id of ['sheetIncremental','sheetFullSync'])if($(id))$(id).disabled=!adminAllowed||q.busy;
    if(q.last_sync_at&&V.lastSheetAt&&q.last_sync_at!==V.lastSheetAt){V.lastSheetAt=q.last_sync_at;toast('Google Sheets sincronizado. Recalculando indicadores…');refresh();}
  }catch(e){if($('sheetProgress'))$('sheetProgress').textContent=e.message}};
  if(adminAllowed){
    $('sheetSave').onclick=async()=>{try{const r=await api('/api/sheets/configure',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({spreadsheet_id:$('sheetID').value,credential_path:$('sheetKeyPath').value,interval_minutes:Number($('sheetInterval').value),full_every_hours:Number($('sheetFull').value),enabled:true})});toast('Conexión guardada. Pruebe el acceso y sincronice.');$('sheetKeyPath').value='';put()}catch(e){toast(e.message)}};
    $('sheetTest').onclick=async()=>{try{const r=await api('/api/sheets/test',{method:'POST'});toast(`Acceso correcto a ${r.title}. Pestañas: ${r.available.length}`);put()}catch(e){toast(e.message)}};
    for(const [id,full] of [['sheetIncremental',false],['sheetFullSync',true]])$(id).onclick=async()=>{try{await api('/api/sheets/sync',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({full})});toast('Se inició la sincronización; el progreso aparecerá aquí.');put()}catch(e){toast(e.message)}};
    $('sheetStop').onclick=async()=>{if(!confirm('¿Detener próximas sincronizaciones automáticas? Los datos locales se conservan.'))return;try{await api('/api/sheets/disable',{method:'POST'});toast('Sincronización desactivada');put()}catch(e){toast(e.message)}};
  }
  await put();if(V.page==='admin'){if(syncPoll)clearInterval(syncPoll);syncPoll=setInterval(()=>{if(V.page==='admin')put()},5500)}
}
async function analyzeFiles(){const generation=refreshID;const files=V.dropFiles?.length?V.dropFiles:[...$('files').files];if(!files.length)return toast('Seleccione uno o más Excel/CSV');const out=$('preview');out.innerHTML='<p>Analizando encabezados, filas y claves de negocio…</p>';let reports=[];for(const file of files){try{const r=await api('/api/import/preview',{method:'POST',headers:{'x-file-name':encodeURIComponent(file.name),'x-sap-cut-date':$('sapCutDate')?.value||'','content-type':'application/octet-stream'},body:await file.arrayBuffer()});if(generation!==refreshID)return;V.staged.push(r);reports.push(`<div class="stat-row"><div><label><input type="checkbox" class="import-select" checked value="${r.id}"> <strong>${esc(file.name)}</strong></label><small style="display:block">${r.records.map(x=>`${esc(x.type||'Desconocido')} · ${x.received} recibidas · ${x.stats?.added||0} nuevas · ${x.stats?.updated||0} actualizadas · ${x.stats?.duplicates||0} duplicadas · ${x.stats?.conflicts||0} conflictos`).join(' / ')}</small></div><span class="chip good">PREVIEW</span></div>`)}catch(e){reports.push(`<div class="stat-row">${esc(file.name)} <span class="chip bad">${esc(e.message)}</span></div>`)}}out.innerHTML=reports.join('')||'No se detectaron fuentes compatibles.';V.dropFiles=null}
async function applyFiles(){if(!V.staged.length)return toast('Primero debe ejecutar una previsualización.');const selected=[...document.querySelectorAll('.import-select:checked')].map(x=>x.value);if(!selected.length)return toast('Marque al menos un archivo en preview.');if(!confirm(`Aplicar ${selected.length} lote(s) al almacenamiento LOCAL? No se modificarán sistemas externos.`))return;try{const r=await api('/api/import/apply',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({ids:selected})});V.staged=[];toast('Datos aplicados: '+r.results.map(x=>`${x.type} +${x.added} / ${x.updated} actualizadas`).join(', '));await refresh();go('admin')}catch(e){toast(e.message)}}
function sourceSummary(){
  const status=V.status||{},access=status.access?.state||(!V.authenticated?'required':'authenticated'),sheet=status.sheets?.state;
  const sheetLabel=({SIN_CONFIGURAR:'Sin configurar',CONECTADO:'Lectura confirmada',SINCRONIZANDO:'Sincronizando',PRECARGADOS:status.deployment==='vercel'?'Snapshot privado':'Snapshot local',ERROR:'Error de lectura',not_configured:'Sin configurar',unavailable:'No disponible',ready:'Disponible',connected:'Lectura confirmada',configured:'Pendiente de lectura'})[sheet]||'Sin verificar';
  const dataLabel=V.data?'Disponible':V.phase==='error'?'No disponible':({ready:'Disponible',not_configured:'Sin configurar',snapshot_required:'Sin snapshot validado',unavailable:'No disponible',pending_migration:'Pendiente de migración'})[status.data?.state]||'Sin verificar';
  return `<div class="source-row">${icon('source')}<div><strong>Google Sheets</strong><small>${status.sheets?.last_sync_at?'Última lectura '+esc(formatDateTime(status.sheets.last_sync_at)):status.sheets?.snapshot_at?'Captura privada '+esc(formatDateTime(status.sheets.snapshot_at)):'Origen operativo de solo lectura'}</small></div><span class="source-state">${esc(sheetLabel)}</span></div><div class="source-row">${icon('inventory')}<div><strong>Dataset de operaciones</strong><small>${V.data?'Consulte los cortes de cada fuente':'No hay un corte disponible para mostrar'}</small></div><span class="source-state">${esc(dataLabel)}</span></div><div class="source-row">${icon('shield')}<div><strong>Acceso al workspace</strong><small>${V.authenticated?'Sesión autorizada para esta ejecución':'Los datos de operación requieren autorización'}</small></div><span class="source-state">${V.authenticated?'Autorizado':access==='not_configured'?'Sin configurar':'Protegido'}</span></div>`;
}
function guideCards(){return `<div class="workspace-guide"><a class="guide-card" href="#inventory" data-route="inventory">${icon('inventory')}<div><strong>Inventario y capital</strong><span>Stock por ubicación, costo contextual y cobertura verificable.</span></div></a><a class="guide-card" href="#forecast" data-route="forecast">${icon('forecast')}<div><strong>Demanda y planificación</strong><span>Historia, pronóstico y criterios para abastecer con evidencia.</span></div></a><a class="guide-card" href="#physical" data-route="physical">${icon('physical')}<div><strong>Tomas físicas</strong><span>El Excel de conteo es la carga manual habitual de la operación.</span></div></a></div>`}
function bindRoutes(){document.querySelectorAll('[data-route]').forEach(a=>a.onclick=e=>{if(e.ctrlKey||e.metaKey||e.shiftKey)return;e.preventDefault();go(a.dataset.route)})}
function renderAvailability(){
  const c=$('content');setFilterAvailability(false);$('warning').hidden=true;
  if(V.phase==='loading'){c.innerHTML=`<div class="loader"><span class="loading-ring" aria-hidden="true"></span>Verificando acceso y fuentes…</div>`;return}
  const status=V.status||{},needsAccess=V.phase==='access'||status.access?.state==='required',unconfigured=status.access?.state==='not_configured',error=V.phase==='error';
  let title=needsAccess?'Acceda a su operación':error?'No se pudo leer la operación':unconfigured?'Prepare un acceso seguro':'Aún no hay datos disponibles';
  let description=needsAccess?'Ingrese la clave de acceso autorizada para consultar inventario, consumo y planificación.':error?'Reintente la lectura. Si el problema continúa, consulte el estado de las fuentes y la configuración del entorno.':unconfigured?'Este entorno necesita la configuración de acceso y una fuente de datos verificada para habilitar los indicadores.':'Los indicadores estarán disponibles cuando exista una fuente verificada. Consulte la salud de las fuentes para revisar el siguiente paso.';
  if(V.page==='physical'&&!needsAccess){title='Toma física lista para su próximo conteo';description='La carga habitual es un Excel de conteo físico por técnico, fecha y SKU. Primero se requiere acceso autorizado y almacenamiento disponible; el archivo se valida antes de aplicarse.'}
  if(V.page==='admin'&&!needsAccess){title=unconfigured?'Configuración del entorno pendiente':'Administración de las fuentes';description='La configuración de acceso y de fuentes se realiza en el entorno del servidor. Google Sheets se mantiene como origen de solo lectura; los importadores de recuperación se usan en contingencia.'}
  const login=needsAccess?`<form id="accessForm" class="access-form"><label for="accessToken">Clave de acceso</label><div class="access-row"><input id="accessToken" name="token" type="password" autocomplete="current-password" spellcheck="false" required aria-describedby="accessHint accessError"><button class="btn-primary" id="accessSubmit" type="submit">Entrar al workspace</button></div><small id="accessHint">Use la clave autorizada para este entorno.</small><p class="form-error" id="accessError" role="alert"></p></form>`:`<div class="availability-actions"><button class="btn-primary" id="retryData">Reintentar lectura</button><a href="#quality" class="btn-quiet" data-route="quality">Revisar fuentes</a></div>`;
  c.innerHTML=(V.page==='quality'?`<section class="source-health"><h2>Salud de fuentes</h2><p>El estado corresponde a la última comprobación de esta sesión. Una configuración disponible no acredita una sincronización exitosa.</p>${sourceSummary()}<div class="availability-actions" style="margin-top:18px"><button class="btn-primary" id="retryData">Comprobar de nuevo</button>${V.authenticated?'<button class="btn-quiet" id="stateLogout">Cerrar sesión</button>':''}</div></section>`:`<section class="availability"><div class="availability-main"><div class="state-icon">${icon(needsAccess?'lock':error?'refresh':V.page==='physical'?'physical':'source')}</div><h2>${esc(title)}</h2><p>${esc(description)}</p>${login}${error&&V.error?`<p class="help-text" style="margin-top:14px">${esc(V.error)}</p>`:''}${V.authenticated?'<button class="btn-quiet" id="stateLogout" style="margin-top:14px">Cerrar sesión</button>':''}</div><aside class="availability-aside"><h3>Disponibilidad del workspace</h3>${sourceSummary()}<div class="assurance">${icon('shield')}Sin corte verificado, no se calculan indicadores.</div></aside></section>`)+guideCards();
  if($('retryData'))$('retryData').onclick=refresh;if($('stateLogout'))$('stateLogout').onclick=logout;
  if($('accessForm'))$('accessForm').onsubmit=async e=>{e.preventDefault();const input=$('accessToken'),button=$('accessSubmit'),out=$('accessError');button.disabled=true;button.textContent='Verificando…';out.textContent='';input.removeAttribute('aria-invalid');try{await api('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token:input.value})});input.value='';await refresh()}catch(error){out.textContent=error.status===401?'La clave no es válida. Verifique la clave autorizada e intente de nuevo.':error.message;input.setAttribute('aria-invalid','true');input.focus()}finally{if($('accessSubmit')){button.disabled=false;button.textContent='Entrar al workspace'}}};
  bindRoutes();
}
function cloudAdministration(c){c.innerHTML=heading('Administración del entorno','Acceso y fuentes configurados en el servidor. Las operaciones de origen son de solo lectura.')+`<section class="source-health">${sourceSummary()}<div class="availability-actions" style="margin-top:18px"><button class="btn-primary" id="adminRetry">Comprobar fuentes</button><button class="btn-quiet" id="adminLogout">Cerrar sesión</button></div></section><div class="notice-unit"><b>Contingencia administrativa</b><span>La recuperación de históricos y los importadores legacy requieren el entorno local autorizado. La carga manual habitual es el Excel de toma física.</span></div>`+guideCards();$('adminRetry').onclick=refresh;$('adminLogout').onclick=logout;bindRoutes()}
function physicalWorkspace(c,d){
  const cloud=V.status?.deployment==='vercel',canImport=!cloud&&V.authenticated;
  if(cloud)return cloudPhysicalWorkspace(c,d);
  c.innerHTML=`<section class="physical-intro">${icon('physical')}<div><h2>Excel de toma física</h2><p>Registre el conteo por técnico, fecha y SKU. La previsualización permite revisar hojas, filas y duplicados antes de aplicar. El último conteo válido sustituye al anterior para ese técnico y material.</p></div>${canImport?'<button class="btn-primary" id="openPhysicalUpload">Cargar Excel</button>':''}</section><div id="physicalUpload" class="panel physical-upload" ${canImport?'hidden':''}>${!canImport?(cloud?'<h3>Carga de Excel en el entorno local</h3><p>La importación de tomas físicas requiere el entorno local autorizado. Los conteos disponibles y sus intervalos se pueden consultar en esta vista.</p>':'<h3>Autorice la carga del conteo</h3><p>Ingrese con la clave administrativa de esta ejecución para previsualizar y aplicar el Excel.</p><a href="#admin" data-route="admin" class="btn-quiet">Abrir acceso administrativo</a>'):`<h3>Validar un nuevo conteo</h3><p>Use un archivo dedicado a tomas físicas. Se requieren fecha, código de técnico, SKU y conteo físico numérico. Se aceptan cantidades cero; los registros anulados no sustituyen un conteo válido.</p><div class="dropzone" id="physicalDrop"><strong>Seleccione el Excel del conteo</strong><small>Encabezados del origen: Toma, Fecha, Código técnico, SKU y Conteo físico.</small><input id="physicalFiles" name="physical-files" type="file" accept=".xlsx,.xlsm" aria-label="Excel de toma física" multiple></div><div class="availability-actions"><button class="btn-primary" id="analyzePhysical">Previsualizar y validar</button><button class="btn-quiet" id="applyPhysical" disabled>Aplicar conteos validados</button></div><div id="physicalPreview" class="import-log" aria-live="polite"><p>No hay archivos preparados.</p></div>`}</div><div id="physicalAnalysis"></div>`;
  if(d.physical?.latest?.length)physical($('physicalAnalysis'),d);else $('physicalAnalysis').innerHTML=empty('Aún no hay conteos físicos válidos. Cargue un Excel de toma física para crear el primer corte.');bindRoutes();
  if(canImport){$('openPhysicalUpload').onclick=()=>{$('physicalUpload').hidden=!$('physicalUpload').hidden;if(!$('physicalUpload').hidden)$('physicalFiles').focus()};$('analyzePhysical').onclick=previewPhysical;$('applyPhysical').onclick=applyPhysical;const drop=$('physicalDrop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');V.physicalFiles=[...e.dataTransfer.files];toast(V.physicalFiles.length+' archivos seleccionados')}}
}
async function previewPhysical(){
  const generation=refreshID;const files=V.physicalFiles?.length?V.physicalFiles:[...$('physicalFiles').files];if(!files.length)return toast('Seleccione un Excel de toma física.');
  const out=$('physicalPreview');out.innerHTML='<p>Validando hojas, encabezados y duplicados…</p>';$('analyzePhysical').disabled=true;$('applyPhysical').disabled=true;V.physicalStaged=[];const reports=[];
  for(const file of files){try{if(!/\.xls[mx]$/i.test(file.name))throw Error('Seleccione un archivo Excel XLSX o XLSM.');const result=await api('/api/import/preview',{method:'POST',headers:{'x-file-name':encodeURIComponent(file.name),'content-type':'application/octet-stream'},body:await file.arrayBuffer()});if(generation!==refreshID)return;const records=result.records||[];
    if(!records.length||records.some(record=>record.type!=='physical_counts'||record.error))throw Error('El archivo debe contener únicamente hojas reconocidas de toma física. Separe otras fuentes para evitar aplicar datos ajenos al conteo.');
    V.physicalStaged.push(result);reports.push(`<div class="stat-row"><div><strong>${esc(file.name)}</strong>${records.map(record=>`<small style="display:block">${esc(record.sheet)}: ${nfmt(record.received)} filas · ${nfmt(record.stats?.added)} nuevas · ${nfmt(record.stats?.updated)} actualizadas · ${nfmt(record.stats?.duplicates)} duplicadas · ${nfmt(record.stats?.conflicts)} conflictos</small>`).join('')}</div><span class="chip good">Toma reconocida</span></div>`);
  }catch(error){reports.push(`<div class="stat-row"><strong>${esc(file.name)}</strong><span class="warning-inline">${esc(error.message)}</span></div>`)}}
  if(!$('physicalPreview'))return;out.innerHTML=reports.join('');$('analyzePhysical').disabled=false;$('applyPhysical').disabled=!V.physicalStaged.length;V.physicalFiles=null;
}
async function applyPhysical(){if(!V.physicalStaged?.length)return;if(!confirm('¿Aplicar los conteos previsualizados al almacenamiento local? Se conserva el histórico y no se modifica Google Sheets.'))return;const button=$('applyPhysical');button.disabled=true;try{await api('/api/import/apply',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({ids:V.physicalStaged.map(x=>x.id)})});V.physicalStaged=[];toast('Conteos aplicados. Actualizando el último conteo válido…');await refresh();go('physical')}catch(error){toast(error.message);if($('applyPhysical'))button.disabled=false}}

// ---- Cloud: toma física persistente (vista previa -> aplicar -> historial / reversión) ----
const PHYSICAL_CHANGE={NUEVO:['good','Nuevo'],ACTUALIZA:['warn','Corrige'],SIN_CAMBIO:['','Sin cambio']};
function cloudPhysicalWorkspace(c,d){
  const ph=V.status?.physical||{},admin=V.status?.access?.role==='admin',ready=ph.state==='LISTO';
  const blocked=ph.state==='SIN_CONFIGURAR'?['Administración Cloud sin configurar','El servidor aún no define una clave de administración separada (GREENCALL_ADMIN_KEY). Los conteos existentes se pueden consultar; la carga queda deshabilitada.']
    :ph.state==='SIN_CREDENCIALES'?['Falta la conexión privada de escritura','El servidor no tiene la credencial de escritura para tomas físicas (GREENCALL_PHYSICAL_DATABASE_URL). No se simula ninguna carga.']
    :!admin?['Se requiere la clave de administración','Su sesión es de consulta. Para cargar o revertir una toma física, cierre sesión e ingrese con la clave de administración.']:null;
  c.innerHTML=`<section class="physical-intro">${icon('physical')}<div><h2>Excel de toma física</h2><p>Carga habitual del conteo por técnico, fecha y SKU. Cada archivo se valida fila por fila contra el catálogo y los técnicos del snapshot activo; al aplicarlo se crea un lote auditable que puede revertirse sin borrar historial. Google Sheets no se modifica.</p></div></section>`
   +`<div class="panel physical-upload" id="physicalUpload">${blocked?`<h3>${esc(blocked[0])}</h3><p>${esc(blocked[1])}</p><span class="chip warn">${esc(ph.state||'NO DISPONIBLE')}</span>`
   :`<h3>Validar un nuevo conteo</h3><p>Un archivo por lote. Columnas requeridas: Toma, Fecha, Código técnico, SKU y Conteo físico (use 0 si no hay existencias). Máximo 4 MiB.</p><div class="dropzone" id="physicalDrop"><strong>Seleccione el Excel del conteo</strong><small>XLSX o XLSM. Las demás hojas del libro se ignoran y se informan.</small><input id="physicalFiles" name="physical-file" type="file" accept=".xlsx,.xlsm" aria-label="Excel de toma física"></div><div class="availability-actions"><button class="btn-primary" id="analyzePhysical">Previsualizar y validar</button><button class="btn-quiet" id="applyPhysical" disabled>Aplicar lote validado</button></div><div id="physicalPreview" class="import-log physical-preview" aria-live="polite"><p>No hay archivo preparado.</p></div>`}</div>`
   +`<div class="panel" style="margin-bottom:20px"><div class="table-tools"><h3>Historial de lotes</h3><button class="btn-quiet" id="physicalHistoryReload">Actualizar</button></div><div id="physicalHistory" aria-live="polite"><p class="help-text">Cargando historial…</p></div></div><div id="physicalAnalysis"></div>`;
  if(d.physical?.latest?.length)physical($('physicalAnalysis'),d);else $('physicalAnalysis').innerHTML=empty('Aún no hay conteos físicos válidos en el snapshot activo.');
  bindRoutes();$('physicalHistoryReload').onclick=loadPhysicalHistory;loadPhysicalHistory();
  if(!blocked&&ready){
    $('analyzePhysical').onclick=cloudPreviewPhysical;$('applyPhysical').onclick=cloudApplyPhysical;
    const drop=$('physicalDrop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');
    drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');V.physicalFiles=[...e.dataTransfer.files].slice(0,1);toast('Archivo seleccionado: '+(V.physicalFiles[0]?.name||''))};
  }
}
function physicalIssuesTable(issues){
  if(!issues?.length)return '<p class="help-text">Sin observaciones: todas las filas cumplen el contrato.</p>';
  return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Fila</th><th>Hoja</th><th>Severidad</th><th>Campo</th><th>Detalle</th></tr></thead><tbody>${issues.slice(0,200).map(i=>`<tr><td class="num">${esc(i.row)}</td><td>${esc(i.sheet)}</td><td><span class="chip ${i.severity==='error'?'bad':'warn'}">${i.severity==='error'?'Error':'Aviso'}</span></td><td>${esc(i.field)}</td><td>${esc(i.message)}</td></tr>`).join('')}</tbody></table></div>`;
}
function physicalChangesTable(changes){
  if(!changes?.length)return '';
  return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Fila</th><th>Técnico</th><th>SKU</th><th>Fecha</th><th class="num">Conteo</th><th>Unidad</th><th class="num">Conteo previo</th><th>Fecha previa</th><th>Efecto</th></tr></thead><tbody>${changes.map(x=>{const [cls,label]=PHYSICAL_CHANGE[x.change]||['',x.change];return `<tr><td class="num">${esc(x.row)}</td><td>${esc(x.tech)}${x.tech_name?`<small style="display:block">${esc(x.tech_name)}</small>`:''}</td><td>${esc(x.sku)}${x.description?`<small style="display:block">${esc(x.description)}</small>`:''}</td><td>${esc(x.date)}</td><td class="num">${nfmt(x.count)}</td><td>${esc(x.unit)}</td><td class="num">${nfmt(x.previous_count)}</td><td>${esc(x.previous_date||'—')}</td><td><span class="chip ${cls}">${esc(label)}</span></td></tr>`}).join('')}</tbody></table></div>`;
}
function renderPhysicalPreview(p){
  const s=p.stats||{},blocked=p.blocked_reason==='VALIDATION_FAILED'?'El archivo tiene errores bloqueantes. Corríjalos en el Excel y vuelva a analizarlo.':p.blocked_reason==='NO_CHANGES'?'El archivo no contiene conteos nuevos ni correcciones respecto al snapshot activo.':'';
  const units=(s.by_unit||[]).map(u=>`<span class="source-chip">${esc(u.unit)}: <b>${nfmt(u.quantity)}</b> en ${nfmt(u.rows)} filas</span>`).join('');
  return `<div class="stat-row"><div><strong>${esc(p.file?.filename)}</strong><small style="display:block">Hojas de toma: ${esc((p.file?.sheets||[]).join(', '))}${p.file?.ignored_sheets?.length?' · Ignoradas: '+esc(p.file.ignored_sheets.join(', ')):''} · Base: snapshot ${esc(String(p.base_snapshot?.id||'').slice(0,8))}</small></div><span class="chip ${p.can_apply?'good':'bad'}">${p.can_apply?'Listo para aplicar':'Bloqueado'}</span></div>`
   +`<div class="admin-cards" style="margin:12px 0">${[['Filas leídas',s.rows_read],['Válidas',s.valid],['Errores',s.errors],['Avisos',s.warnings],['Nuevas',s.new],['Correcciones',s.updated],['Sin cambio',s.unchanged],['Técnicos',s.technicians]].map(([k,v])=>`<div class="mini-card">${esc(k)}<b>${nfmt(v)}</b></div>`).join('')}</div>`
   +`<p class="help-text">Período del conteo: ${esc(s.date_min||'—')} a ${esc(s.date_max||'—')}. Totales por unidad (no se suman entre unidades):</p><div class="chip-group" style="margin:6px 0 14px">${units||'<span class="help-text">—</span>'}</div>`
   +(blocked?`<p class="warning-inline">${esc(blocked)}</p>`:'')
   +`<h3 style="margin-top:14px">Observaciones${p.issues_truncated?' (primeras 500)':''}</h3>${physicalIssuesTable(p.issues)}`
   +(p.changes?.length?`<h3 style="margin-top:14px">Efecto sobre el último conteo válido${p.changes_truncated?' (primeras 200 filas)':''}</h3>${physicalChangesTable(p.changes)}`:'');
}
async function cloudPreviewPhysical(){
  const generation=refreshID,file=(V.physicalFiles?.length?V.physicalFiles:[...$('physicalFiles').files])[0];
  if(!file)return toast('Seleccione un Excel de toma física.');
  if(!/\.xls[mx]$/i.test(file.name))return toast('Seleccione un archivo Excel XLSX o XLSM.');
  if(file.size>4*1024*1024)return toast('El archivo supera 4 MiB; divida la toma por técnico o fecha.');
  const out=$('physicalPreview');out.innerHTML='<p>Validando filas contra catálogo y técnicos…</p>';$('analyzePhysical').disabled=true;$('applyPhysical').disabled=true;V.physicalCloud=null;
  try{
    const buffer=await file.arrayBuffer();
    const p=await api('/api/physical/preview',{method:'POST',headers:{'x-file-name':encodeURIComponent(file.name),'content-type':'application/octet-stream'},body:buffer});
    if(generation!==refreshID||!$('physicalPreview'))return;
    out.innerHTML=renderPhysicalPreview(p);
    if(p.can_apply)V.physicalCloud={buffer,name:file.name,sha:p.file.sha256,base:p.base_snapshot.id,stats:p.stats};
    $('applyPhysical').disabled=!p.can_apply;
  }catch(error){if($('physicalPreview'))out.innerHTML=`<div class="stat-row"><strong>${esc(file.name)}</strong><span class="warning-inline">${esc(error.message)}</span></div>`}
  finally{if($('analyzePhysical'))$('analyzePhysical').disabled=false;V.physicalFiles=null}
}
async function cloudApplyPhysical(){
  const staged=V.physicalCloud;if(!staged)return;
  if(!confirm(`¿Aplicar ${nfmt(staged.stats.new)} conteos nuevos y ${nfmt(staged.stats.updated)} correcciones? Se crea un lote auditable y reversible; Google Sheets no se modifica.`))return;
  const button=$('applyPhysical');button.disabled=true;
  try{
    const r=await api('/api/physical/apply',{method:'POST',headers:{'x-file-name':encodeURIComponent(staged.name),'x-file-sha256':staged.sha,'x-base-snapshot':staged.base,'content-type':'application/octet-stream'},body:staged.buffer});
    V.physicalCloud=null;toast(r.idempotent?'Este lote ya estaba aplicado; no se duplicó.':'Lote aplicado. Actualizando indicadores…');await refresh();go('physical');
  }catch(error){toast(error.code==='SNAPSHOT_CONFLICT'?'Los datos cambiaron desde la vista previa. Vuelva a analizar el archivo.':error.message);V.physicalCloud=error.code==='SNAPSHOT_CONFLICT'?null:staged;if($('applyPhysical'))button.disabled=!V.physicalCloud}
}
async function loadPhysicalHistory(){
  const box=$('physicalHistory');if(!box)return;
  try{
    const h=await api('/api/physical/batches');if(!$('physicalHistory'))return;
    V.physicalActive=h.active_snapshot?.id||null;const admin=V.status?.access?.role==='admin'&&V.status?.physical?.state==='LISTO';
    if(!h.batches?.length){box.innerHTML='<p class="help-text">Aún no hay lotes Cloud. Los conteos previos al módulo Cloud se conservan como historial base.</p>';return}
    box.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha (UTC)</th><th>Acción</th><th>Archivo</th><th class="num">Filas</th><th>Período</th><th>Estado</th><th></th></tr></thead><tbody>${h.batches.map(b=>{const active=b.action==='IMPORT'&&!b.reverted_by;return `<tr><td>${esc(String(b.created_at).slice(0,16).replace('T',' '))}</td><td>${b.action==='IMPORT'?'Importación':'Reversión'}</td><td>${esc(b.filename||'—')}${b.file_sha256?`<small style="display:block">SHA ${esc(b.file_sha256.slice(0,12))}</small>`:''}</td><td class="num">${nfmt(b.action==='IMPORT'?b.row_count:b.stats?.rows_removed)}</td><td>${esc(b.stats?.date_min?b.stats.date_min+' a '+b.stats.date_max:'—')}</td><td><span class="chip ${b.action==='REVERT'?'':active?'good':'warn'}">${b.action==='REVERT'?'Registro':active?'Vigente':'Revertido'}</span></td><td>${admin&&active?`<button class="btn-quiet" data-revert="${esc(b.id)}">Revertir</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`;
    box.querySelectorAll('[data-revert]').forEach(btn=>btn.onclick=()=>revertPhysical(btn.dataset.revert,btn));
  }catch(error){if($('physicalHistory'))box.innerHTML=`<p class="warning-inline">${esc(error.code==='SIN_CREDENCIALES'?'Historial no disponible: falta la conexión privada de tomas físicas.':error.message)}</p>`}
}
async function revertPhysical(id,button){
  if(!V.physicalActive)return toast('No hay snapshot activo para revertir.');
  if(!confirm('¿Revertir este lote? Sus conteos dejan de aplicarse y se restaura el valor anterior. El lote y la reversión quedan registrados.'))return;
  button.disabled=true;
  try{await api('/api/physical/revert',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({batch_id:id,base_snapshot_id:V.physicalActive})});toast('Lote revertido. Actualizando indicadores…');await refresh();go('physical')}
  catch(error){toast(error.code==='SNAPSHOT_CONFLICT'?'Los datos cambiaron; actualice el historial e intente de nuevo.':error.message);button.disabled=false}
}

// Auditoría de cobertura de costos: fuente, base y motivo por material activo (sin ₡0 sustitutos).
function costCoveragePanel(c,d){const cov=d.quality?.cost_coverage;if(!cov?.items?.length)return;const BASIS={ÚNICO:'Precio único',CONTEXTO:'Contexto exacto',REFERENCIA:'Referencia valorada',DESCRIPCIÓN:'Descripción exacta',ALIAS:'Alias revisado',CONFLICTO:'Conflicto de precios',SIN_COSTO:'Sin costo verificable'};const rows=cov.items.map(i=>({...i,label:i.description||i.sku||'(sin descripción en origen)',basis_label:BASIS[i.basis]||i.basis,detail:i.cost===null?i.reason:i.source}));const box=document.createElement('section');box.innerHTML=heading('Cobertura de costos','Resolvedor único: SKU + contexto → precio único → referencia valorada → descripción/alias revisado. Sin precio verificable no se imputa ₡0.',`${nfmt(cov.resolved)} de ${nfmt(cov.total)} materiales (${nfmt(Math.round(100*cov.resolved/cov.total))} %)`)+`<div class="panel">${table(rows,[['sku','SKU'],['label','Material'],['unit','UM'],['cost','Costo unitario sin IVA','money'],['basis_label','Base','chip'],['detail','Fuente o motivo']],20)}</div>`;c.appendChild(box)}

document.addEventListener('DOMContentLoaded',()=>{init();setInterval(async()=>{try{const s=await api('/api/status');if(s.deployment==='vercel'&&V.authenticated&&!s.authenticated){++refreshID;++filterRequest;V.data=null;V.authenticated=false;V.status=s;V.phase=s.access?.state==='required'?'access':'empty';syncStatus(s);render();return}if(s.sheets?.last_sync_at&&V.lastSheetAt&&s.sheets.last_sync_at!==V.lastSheetAt){V.lastSheetAt=s.sheets.last_sync_at;await refresh();toast('Indicadores actualizados desde Google Sheets');}}catch{}},60000)});
